-- =====================================================================
-- Una sola fuente de datos: ciudades, sucursales y catálogo de la tienda en la base de datos.
-- Generado a partir de los datos que antes estaban escritos en el código de la página.
-- =====================================================================

-- 1. Ciudades: limpiar nombres, unir repetidas y agregar departamento / cobertura de domicilio
ALTER TABLE "ciudad" ADD COLUMN "departamento" TEXT;
ALTER TABLE "ciudad" ADD COLUMN "domicilio" BOOLEAN NOT NULL DEFAULT false;
UPDATE "ciudad" SET "ciudad" = btrim(regexp_replace("ciudad", '\s+', ' ', 'g'));
UPDATE "ciudad" SET "ciudad" = 'Bogotá' WHERE lower("ciudad") IN ('bogota', 'bogotá d.c.', 'bogota d.c.', 'bogotá dc', 'bogota dc');
UPDATE "ciudad" SET "ciudad" = 'Medellín' WHERE lower("ciudad") = 'medellin';
UPDATE "ciudad" SET "ciudad" = 'Itagüí' WHERE lower("ciudad") IN ('itagui', 'itaguí', 'itagüi');

CREATE TEMP TABLE ciudad_canon AS
  SELECT ciudad_id AS viejo, min(ciudad_id) OVER (PARTITION BY lower(ciudad)) AS nuevo FROM "ciudad";
UPDATE "empresa_cliente" e SET "ciudad_id" = c.nuevo FROM ciudad_canon c WHERE e."ciudad_id" = c.viejo AND c.viejo <> c.nuevo;
UPDATE "inventario_producto" i SET "ciudad_id" = c.nuevo FROM ciudad_canon c WHERE i."ciudad_id" = c.viejo AND c.viejo <> c.nuevo;
DELETE FROM "ciudad" x USING ciudad_canon c WHERE x."ciudad_id" = c.viejo AND c.viejo <> c.nuevo;
DROP TABLE ciudad_canon;
CREATE UNIQUE INDEX "ciudad_ciudad_key" ON "ciudad"("ciudad");

