-- 2. Ciudad del usuario como relación (se conserva el texto por compatibilidad)
ALTER TABLE "usuario" ADD COLUMN "ciudad_id" INTEGER;
UPDATE "usuario" SET "city" = 'Medellín' WHERE lower(btrim("city")) = 'medellin';
UPDATE "usuario" u SET "ciudad_id" = c."ciudad_id" FROM "ciudad" c WHERE lower(btrim(u."city")) = lower(c."ciudad");
ALTER TABLE "usuario" ADD CONSTRAINT "usuario_ciudad_id_fkey" FOREIGN KEY ("ciudad_id") REFERENCES "ciudad"("ciudad_id") ON DELETE SET NULL ON UPDATE CASCADE;

-- 3. Sucursales (tiendas) y bodegas
CREATE TABLE "sucursal" (
    "sucursal_id" TEXT NOT NULL,
    "nombre" TEXT NOT NULL,
    "ciudad_id" INTEGER NOT NULL,
    "tipo" TEXT NOT NULL DEFAULT 'tienda',
    "direccion" TEXT,
    "telefono" TEXT,
    "email" TEXT,
    "horario" TEXT,
    "listo_en_horas" INTEGER,
    "lat" DOUBLE PRECISION,
    "lng" DOUBLE PRECISION,
    "orden" INTEGER NOT NULL DEFAULT 0,
    "activo" BOOLEAN NOT NULL DEFAULT true,
    CONSTRAINT "sucursal_pkey" PRIMARY KEY ("sucursal_id")
);
ALTER TABLE "sucursal" ADD CONSTRAINT "sucursal_ciudad_id_fkey" FOREIGN KEY ("ciudad_id") REFERENCES "ciudad"("ciudad_id") ON DELETE RESTRICT ON UPDATE CASCADE;

