-- 4. Inventario y pedidos ligados a la sucursal/bodega
ALTER TABLE "inventario_producto" ADD COLUMN "sucursal_id" TEXT;
ALTER TABLE "inventario_producto" ADD CONSTRAINT "inventario_producto_sucursal_id_fkey" FOREIGN KEY ("sucursal_id") REFERENCES "sucursal"("sucursal_id") ON DELETE SET NULL ON UPDATE CASCADE;
UPDATE "inventario_producto" i SET "sucursal_id" = s."sucursal_id" FROM "sucursal" s WHERE lower(btrim(i."nombre_bodega")) = lower(s."nombre");
-- Cualquier otra bodega creada a mano queda registrada como sucursal tipo bodega
INSERT INTO "sucursal" ("sucursal_id", "nombre", "ciudad_id", "tipo", "orden")
  SELECT DISTINCT ON (lower(btrim("nombre_bodega")))
         'bodega-' || substr(md5(lower(btrim("nombre_bodega"))), 1, 10), btrim("nombre_bodega"), "ciudad_id", 'bodega', 200
  FROM "inventario_producto" WHERE "sucursal_id" IS NULL AND "nombre_bodega" IS NOT NULL AND btrim("nombre_bodega") <> ''
  ON CONFLICT DO NOTHING;
UPDATE "inventario_producto" i SET "sucursal_id" = s."sucursal_id" FROM "sucursal" s WHERE i."sucursal_id" IS NULL AND lower(btrim(i."nombre_bodega")) = lower(s."nombre");

ALTER TABLE "orden" ADD COLUMN "sucursal_id" TEXT;
ALTER TABLE "orden" ADD CONSTRAINT "orden_sucursal_id_fkey" FOREIGN KEY ("sucursal_id") REFERENCES "sucursal"("sucursal_id") ON DELETE SET NULL ON UPDATE CASCADE;
UPDATE "orden" o SET "sucursal_id" = s."sucursal_id" FROM "sucursal" s
  WHERE o."metodo_entrega" = 'recoger_tienda' AND o."sucursal_id" IS NULL AND o."direccion_entrega" ILIKE s."nombre" || '%';

-- 5. Catálogo de la tienda: líneas, presentaciones (tabla producto) y colores
CREATE TABLE "linea_producto" (
    "linea_id" TEXT NOT NULL,
    "sku" TEXT,
    "nombre" TEXT NOT NULL,
    "marca" TEXT,
    "subtitulo" TEXT,
    "categoria" TEXT NOT NULL,
    "categoria_etiqueta" TEXT,
    "badge" TEXT,
    "descripcion" TEXT,
    "caracteristicas" JSONB,
    "ficha" JSONB,
    "imagen" TEXT,
    "es_herramienta" BOOLEAN NOT NULL DEFAULT false,
    "rendimiento_galon" DOUBLE PRECISION,
    "manos_default" INTEGER,
    "color_default" TEXT,
    "tamano_default" TEXT,
    "orden" INTEGER NOT NULL DEFAULT 0,
    "activo" BOOLEAN NOT NULL DEFAULT true,
    CONSTRAINT "linea_producto_pkey" PRIMARY KEY ("linea_id")
);

CREATE TABLE "color_producto" (
    "color_producto_id" TEXT NOT NULL,
    "linea_id" TEXT NOT NULL,
    "color_key" TEXT NOT NULL,
    "nombre" TEXT NOT NULL,
    "hex" TEXT NOT NULL,
    "codigo" TEXT,
    "orden" INTEGER NOT NULL DEFAULT 0,
    "activo" BOOLEAN NOT NULL DEFAULT true,
    CONSTRAINT "color_producto_pkey" PRIMARY KEY ("color_producto_id")
);
CREATE UNIQUE INDEX "color_producto_linea_id_color_key_key" ON "color_producto"("linea_id", "color_key");
ALTER TABLE "color_producto" ADD CONSTRAINT "color_producto_linea_id_fkey" FOREIGN KEY ("linea_id") REFERENCES "linea_producto"("linea_id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "producto" ADD COLUMN "linea_id" TEXT;
ALTER TABLE "producto" ADD COLUMN "tamano_id" TEXT;
ALTER TABLE "producto" ADD COLUMN "tamano_nombre" TEXT;
ALTER TABLE "producto" ADD COLUMN "capacidad_litros" DOUBLE PRECISION;
ALTER TABLE "producto" ADD COLUMN "sku" TEXT;
ALTER TABLE "producto" ADD COLUMN "orden" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "producto" ADD COLUMN "activo" BOOLEAN NOT NULL DEFAULT true;
CREATE UNIQUE INDEX "producto_linea_id_tamano_id_key" ON "producto"("linea_id", "tamano_id");
ALTER TABLE "producto" ADD CONSTRAINT "producto_linea_id_fkey" FOREIGN KEY ("linea_id") REFERENCES "linea_producto"("linea_id") ON DELETE SET NULL ON UPDATE CASCADE;

