-- Koraza Protección Sol & Lluvia
INSERT INTO "linea_producto" ("linea_id", "sku", "nombre", "marca", "subtitulo", "categoria", "categoria_etiqueta", "badge", "descripcion", "caracteristicas", "ficha", "imagen", "es_herramienta", "rendimiento_galon", "manos_default", "color_default", "tamano_default", "orden")
VALUES ('koraza-sol-lluvia', 'KRZ-SOL-LLUVIA', 'Koraza Protección Sol & Lluvia', 'ColorLink Recubrimientos', 'Pintura impermeabilizante elastomérica de máxima duración ante intemperie y rayos UV', 'construccion', 'Fachadas & Exterior', 'Máxima Duración', 'Pintura exterior 100% acrílica base agua de alta tecnología hidrorrepelente y elastomérica. Sella microfisuras vivas de hasta 1 mm gracias a su polímero flexible que acompaña los movimientos térmicos de contracción y dilatación del revoque sin agrietarse ni desprenderse. Diseñada con pigmentos UV-Shield que no decoloran bajo radiación solar intensa ni climas costeros salinos.', '["Garantía de película intemperie hasta por 10 años certificados","Película elástica microfisuras-proof (puentea grietas de 1 mm)","Escudo antihongos, antialgas y resistencia al caleo o entizamiento","Autolavable con el agua de lluvia: el polvo no se adhiere a la película","No requiere imprimante previo sobre revoques curados en buen estado"]'::jsonb, '{"rendimiento":"30 a 35 m² por galón a 2 manos sobre superficie lisa","secado":"Al tacto 1 hora | Entre manos 3 a 4 horas | Secado total 24 horas","base":"Polímero 100% Acrílico Puro Elastomérico","acabado":"Semimate Satinado Exterior","solvente":"Agua potable (máx 5% en primera mano)"}'::jsonb, '/products/koraza-galon.webp', false, 60, 2, 'blanco-puro', 'galon', 1);
