-- Pintulux Esmalte Sintético Brillante
INSERT INTO "linea_producto" ("linea_id", "sku", "nombre", "marca", "subtitulo", "categoria", "categoria_etiqueta", "badge", "descripcion", "caracteristicas", "ficha", "imagen", "es_herramienta", "rendimiento_galon", "manos_default", "color_default", "tamano_default", "orden")
VALUES ('pintulux-esmalte-brillante', 'PTX-ESM-BRILLANTE', 'Pintulux Esmalte Sintético Brillante', 'ColorLink Recubrimientos', 'Esmalte alquídico de máxima adherencia anticorrosiva para puertas, ventanas y rejas metálicas', 'hogar', 'Esmalte & Metales', 'Brillo Espejo', 'Esmalte sintético brillante a base de resinas alquídicas modificadas que ofrecen una nivelación impecable sin marcas de brocha y un brillo tipo espejo de altísima retención. Protege estructuras metálicas contra la oxidación y embellece maderas interiores y exteriores.', '["Acabado espejo de alto brillo y extraordinaria nivelación","Protección anticorrosiva sobre hierro y acero debidamente fondeados","Lavable, resistente a grasas, humedad y detergentes domésticos","Excelente retención de color sin amarillamiento prematuro"]'::jsonb, '{"rendimiento":"45 a 55 m² por galón a 1 mano / 25 a 30 m² a 2 manos","secado":"Al tacto 4 horas | Repinte 12 horas | Curado duro 48 horas","base":"Alquídica con solvente aromático balanceado","acabado":"Brillante Espejo (>85 UB a 60°)","solvente":"Ajustador Varsol o Thinner fino (10% a 15%)"}'::jsonb, '/products/pintulux-galon.webp', false, 45, 2, 'blanco-brillante', 'galon', 2);
