-- Poliuretano Automotriz 2K Alto Brillo
INSERT INTO "linea_producto" ("linea_id", "sku", "nombre", "marca", "subtitulo", "categoria", "categoria_etiqueta", "badge", "descripcion", "caracteristicas", "ficha", "imagen", "es_herramienta", "rendimiento_galon", "manos_default", "color_default", "tamano_default", "orden")
VALUES ('poliuretano-automotriz-2k', 'AUT-POL-2K', 'Poliuretano Automotriz 2K Alto Brillo', 'ColorLink AutoTech', 'Esmalte poliuretano bicomponente para repintado automotriz, motos y flotas de transporte', 'automotriz', 'Línea Automotriz 2K', 'Calidad OEM', 'Sistema de acabado poliuretano acrílico bicomponente (2K) formulado para el repintado profesional de vehículos particulares, comerciales y maquinaria pesada. Ofrece resistencia superior a la gasolina, químicos de lavado a presión, lluvia ácida y rayones superficiales.', '["Dureza superficial tipo fábrica automotriz (Shore D >80)","Filtro UV estabilizador HALS contra decoloración solar","Curado rápido al aire o acelerado en cabina de horneado (60°C)","Permite pulido y brillado a las 24 horas de aplicado"]'::jsonb, '{"rendimiento":"35 a 40 m² por galón a 2 manos con pistola HVLP","secado":"Libre de polvo 15 min | Para manipulación 4 horas | Pulible 24 horas","base":"Poliuretano Acrílico Hidroxilado + Isocianato Alifático","acabado":"Alto Brillo Cristalline (>95 UB)","solvente":"Thinner Poliuretano Uretano Grado Reactivo"}'::jsonb, '/products/poliuretano-cuarto.webp', false, 70, 2, 'negro-ebano', 'cuarto', 3);
